import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Spectre","description":"","frontmatter":{"title":"Spectre","order":12},"headers":[],"relativePath":"mods/spectre.md","filePath":"mods/spectre.md","lastUpdated":1786957039000}'),i={name:"mods/spectre.md"};function n(l,e,s,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="spectre" tabindex="-1">Spectre <a class="header-anchor" href="#spectre" aria-label="Permalink to &quot;Spectre&quot;">​</a></h1><blockquote><p>An ADOFAI <strong>replay Mod</strong>, built with Harmony and UnityModManager, for precise keyboard input recording and playback.</p><p>Project: <a href="https://github.com/adofaiex/Spectre" target="_blank" rel="noreferrer">https://github.com/adofaiex/Spectre</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="replay-system" tabindex="-1">Replay System <a class="header-anchor" href="#replay-system" aria-label="Permalink to &quot;Replay System&quot;">​</a></h3><p><strong>Recording</strong></p><ul><li>Captures every keyboard event (press/release) with precise song-position timestamps</li><li>Per-floor hit context: angle, overload, auto-status, no-fail protection, free-roam section</li><li>Hit margin distribution and X-accuracy tracking</li><li>Optional: keyboard sound recording via microphone (saved as <code>.wav</code> alongside the replay)</li><li>Late-save, fail-save, auto-save modes</li><li>Manual save before exiting a level</li></ul><p><strong>Playback</strong></p><ul><li>Floor-by-floor replay with exact angle/auto/overload restoration</li><li>Full-run and checkpoint-based playback</li><li>Fast-forward to starting checkpoint</li><li>Legacy hit detection engine (switchable)</li><li>Data integrity verification on load (hash checks for floor path, speed, time, pitch, BPM)</li></ul><h3 id="effect-remover" tabindex="-1">Effect Remover <a class="header-anchor" href="#effect-remover" aria-label="Permalink to &quot;Effect Remover&quot;">​</a></h3><ul><li><strong>Planet</strong>: Orbit, Scale, Radius</li><li><strong>Track</strong>: Animations, Positions, Moves, Colors</li><li><strong>DLC</strong>: Hold Sounds, Hide Icons</li><li><strong>Misc</strong>: Remove All Decorations (or keep conditional-tag-protected ones), Reset Track Opacity, Reset Track Animation, Reset Track Color, Set Camera Zoom</li></ul><p>Override settings: <code>Remove All Decorations</code> (clears all decorations except those tagged by conditional events), <code>Set Camera Zoom</code> (overrides camera zoom 100–1000), <code>Reset Track Animation/Color</code>. Works in both game and editor; editor save buttons are disabled while effect removal is active (configurable).</p><h3 id="key-remapping" tabindex="-1">Key Remapping <a class="header-anchor" href="#key-remapping" aria-label="Permalink to &quot;Key Remapping&quot;">​</a></h3><p>Remap key codes at runtime via the <code>Options.UI</code> tab. Useful for custom keyboard layouts or cross-platform input handling.</p><h3 id="audio-recording" tabindex="-1">Audio Recording <a class="header-anchor" href="#audio-recording" aria-label="Permalink to &quot;Audio Recording&quot;">​</a></h3><p>Record keyboard sounds via connected microphone. Volume and offset adjustable. Audio saved alongside replay file and validated by hash on playback.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Install <a href="https://www.nexusmods.com/site/mods/21" target="_blank" rel="noreferrer">UnityModManager</a> for ADOFAI</li><li>Place <code>Spectre.dll</code> in <code>UnityModManager/ADofAI/Mods/Spectre/</code></li><li>Launch the game and enable Spectre in the mod manager</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p><code>Configs.json</code> is auto-generated next to the DLL on first launch. All settings are exposed in the in-game UI (toggle from UnityModManager mod list).</p><p>Settings are organized into 6 tabs:</p><ul><li><strong>Save Settings</strong> — auto-save, complete-save, late-save, fail-save, manual-save, backup, legacy engine, don&#39;t save on auto/miss</li><li><strong>Replaying Settings</strong> — playback speed, save button position, key limit</li><li><strong>Audio Record Settings</strong> — keyboard sound recording, volume, microphone device, offset</li><li><strong>Mod UI</strong> — text size, language, key remapping</li><li><strong>Debug Settings</strong> — key validation, debug mode, skip verification</li><li><strong>Effect Remover</strong> — per-effect toggles</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Replay format reference and Harmony patching utilities: <a href="./yqlossclientharmony">YqlossClientHarmony</a></li><li>Another ADOFAI replay Mod: <a href="https://github.com/potatoonadofai/Creplay-mod" target="_blank" rel="noreferrer">Creplay-mod</a></li></ul>',23)])])}const h=a(i,[["render",n]]);export{u as __pageData,h as default};
